suspend fun sort(a: IntArray): IntArray = coroutineScope {
    if (a.size < 1024) return@coroutineScope a.sortedArray()      // base case
    val mid = a.size / 2
    val parts = listOf(
        async(Dispatchers.Default) { sort(a.copyOfRange(0, mid)) },
        async(Dispatchers.Default) { sort(a.copyOfRange(mid, a.size)) },
    )
    merge(parts.awaitAll())            // join + combine; a failure cancels the scope
}
